import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const f=JSON.parse('{"title":"成人肌少症食养指南（2026年版）","description":"国家卫健委《成人肌少症食养指南（2026年版）》可执行整理：增肌防跌倒的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人肌少症食养指南（2026年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2026年版","published":"2026-04","source_url":"https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml","status":"现行","tags":["肌少症","老年营养","食养","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人肌少症食养指南（2026年版）》可执行整理：增肌防跌倒的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/sarcopenia-2026.md","filePath":"guides/sarcopenia-2026.md"}'),s={name:"guides/sarcopenia-2026.md"};function i(o,t,g,h,n,p){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="成人肌少症食养指南-2026年版" tabindex="-1">成人肌少症食养指南（2026年版） <a class="header-anchor" href="#成人肌少症食养指南-2026年版" aria-label="Permalink to &quot;成人肌少症食养指南（2026年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>肌肉量减少、肌力下降的成人（尤其老年人）及其照护者（<a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=5" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>七条原则</strong>：蛋白优质足量、三餐均衡分配 → 增加营养密度、膳食细软好吸收 → 按需补充营养、精准增加肌肉 → 主动多元运动、加强抗阻锻炼 → 调理脾胃为本、科学选用食药物质 → 管控基础疾病 → 监测肌少风险、早筛早诊早干预。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=7" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>蛋白质</td><td><strong>1.2～1.5g/kg 体重</strong>（肾功能正常者）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>每餐蛋白质</td><td><strong>20～25g</strong>，三餐均衡分配</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>鱼虾类</td><td><strong>每周 300～500g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>鸡蛋</td><td><strong>每天 1 个</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>奶类</td><td><strong>300～500mL</strong> 或相当量奶制品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>大豆</td><td><strong>每周约 105g</strong> 或相当量豆制品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>畜禽瘦肉</td><td><strong>每周 300～500g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>乳清蛋白补充</td><td><strong>每天 20～40g</strong>（足量蛋白和/或运动 25～30kcal/kg 者）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>抗阻运动</td><td><strong>每周 2～3 次、每次 30～60 分钟</strong>，逐步增加负荷</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>有氧运动</td><td><strong>每周至少 3 次、每次 30 分钟以上</strong>，同时监测心率</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>优质蛋白优先：鱼虾、禽畜瘦肉、蛋、奶、大豆及豆制品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>蛋白质三餐均衡分配，每餐 20～25g</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>增加营养密度，膳食<strong>细软好吸收</strong>（老年人牙口消化特点）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>口服营养补充/乳清蛋白按需使用，全素食者也可补充乳清蛋白</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>按证型调理脾胃，科学选用食药物质</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>管控基础疾病（糖尿病、慢阻肺、肿瘤、肾功能不全等），合理调整方案</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(六)</a></td></tr></tbody></table><h3 id="🏃-动-🩺-测与就医" tabindex="-1">🏃 动 / 🩺 测与就医 <a class="header-anchor" href="#🏃-动-🩺-测与就医" aria-label="Permalink to &quot;🏃 动 / 🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>抗阻运动每周 2～3 次、每次 30～60 分钟，逐步增加负荷</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>有氧运动每周至少 3 次、每次 30 分钟以上，运动同时监测心率</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>老年人定期做肌少症风险筛查与评估（附录5），早筛早诊早干预</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=9" target="_blank" rel="noreferrer">三(七)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=81" target="_blank" rel="noreferrer">附录5</a></td></tr></tbody></table><h2 id="附录怎么用" tabindex="-1">附录怎么用 <a class="header-anchor" href="#附录怎么用" aria-label="Permalink to &quot;附录怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=15" target="_blank" rel="noreferrer">附录1《食物选择》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=17" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=22" target="_blank" rel="noreferrer">附录3《不同地区不同季节食谱示例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=74" target="_blank" rel="noreferrer">附录4《证型食养方举例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/sarcopenia-2026.pdf#page=81" target="_blank" rel="noreferrer">附录5《风险筛查、评估和诊断》</a></strong>。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2026 年版（现行）</td></tr><tr><td>印发时间</td><td>2026 年 4 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml" target="_blank" rel="noreferrer">卫健委通知页</a></td></tr></tbody></table>',18)])])}const u=e(s,[["render",i]]);export{f as __pageData,u as default};
